from pathlib import Path
roots = (Path('products/services'), Path('products/distribution'))
terms = ('checkout', 'download-fulfillment', 'invoice-preflight', 'text-csv', 'checkpoint')
for root in roots:
    for path in sorted(root.iterdir()) if root.is_dir() else []:
        if any(term in path.name for term in terms):
            entries = sorted(str(p) for p in path.rglob('*') if p.is_file() and 'raw' not in p.parts) if path.is_dir() else [str(path)]
            for item in entries[:25]:
                print(item)
